# This file was generated by AI
"""Calculate unweighted and weighted AI vs. human Python code attribution metrics.

This standalone audit script scans all tracked project Python files (excluding
itself and empty ``__init__.py`` files) and computes both raw SLOC percentages
and importance-weighted contribution percentages across four functional
categories:

    1. Core Algorithms & Problem Formulation (weight: 60%)
       Optimization algorithms, problem representations, objective/covariance
       math, constraint repair, configurations, and the top-level entrypoint.
    2. Experiment Runners, CLI & Logging (weight: 15%)
       Batch/single-run orchestration scripts, argparse CLIs, and logging setup.
    3. Testing & Verification (weight: 15%)
       Automated pytest unit and regression test suites.
    4. Plotting, Reporting & Utilities (weight: 10%)
       Matplotlib figure generators, CSV/Markdown/LaTeX summarizers, validators,
       data parsers, and hyperparameter tuning helpers.

Attribution rules (matching the repository's two comment conventions):
    - Files starting with ``# This file was generated by AI`` count 100% as AI.
    - Code enclosed between ``# AI Assisted`` and ``# End AI Assisted`` counts
      as AI; all other code lines count as team-authored (human).
    - SLOC counts non-blank, non-comment (``#``) source lines and excludes the
      attribution marker comments themselves.

How to run (from the repository root):
    python ai_code_metrics.py
    python ai_code_metrics.py --per-file
"""

from __future__ import annotations

import argparse
from collections import defaultdict
from pathlib import Path
import subprocess

SELF_PATH = Path(__file__).name

CORE_ALGORITHM_FILES = {
    "main.py",
    "bees_algorithm/configs.py",
    "bees_algorithm/functions.py",
    "bees_algorithm/interface.py",
    "bees_algorithm/core/bee.py",
    "bees_algorithm/core/solver.py",
    "bees_algorithm/problem/tsp.py",
    "bees_algorithm/problem/continuous.py",
    "bees_algorithm/utils/exceptions.py",
    "bees_algorithm/utils/tracked.py",
    "evolution_strategy/portfolio.py",
    "evolution_strategy/evaluation.py",
    "evolution_strategy/repair.py",
    "evolution_strategy/algorithms.py",
    "evolution_strategy/evolution_strategies.py",
}

RUNNER_CLI_FILES = {
    "logger.py",
    "bees_algorithm/optimise.py",
    "evolution_strategy/optimise.py",
    "evolution_strategy/results.py",
}

CATEGORY_WEIGHTS: dict[str, float] = {
    "Core Algorithms & Formulation": 0.60,
    "Runners, CLI & Logging": 0.15,
    "Testing & Verification": 0.15,
    "Plotting, Reporting & Utilities": 0.10,
}

SCOPES = ("Problem 1 (BA)", "Problem 2 (ES)", "Shared / Root")


def classify_category(rel_path: str) -> str:
    if "/tests/" in rel_path:
        return "Testing & Verification"
    if rel_path in CORE_ALGORITHM_FILES:
        return "Core Algorithms & Formulation"
    if rel_path in RUNNER_CLI_FILES:
        return "Runners, CLI & Logging"
    return "Plotting, Reporting & Utilities"


def classify_scope(rel_path: str) -> str:
    if rel_path.startswith("bees_algorithm/"):
        return "Problem 1 (BA)"
    if rel_path.startswith("evolution_strategy/"):
        return "Problem 2 (ES)"
    return "Shared / Root"


def count_file(path: Path) -> dict[str, int]:
    """Count total and AI-attributed SLOC and non-blank lines in one Python file."""
    lines = path.read_text(encoding="utf-8").splitlines()
    if not lines:
        return {"total_nb": 0, "ai_nb": 0, "total_code": 0, "ai_code": 0}

    full_ai = lines[0].strip() == "# This file was generated by AI"
    in_ai_block = False

    total_nb = 0
    ai_nb = 0
    total_code = 0
    ai_code = 0

    for line in lines:
        stripped = line.strip()
        if stripped == "# This file was generated by AI":
            continue
        if stripped == "# AI Assisted":
            in_ai_block = True
            continue
        if stripped == "# End AI Assisted":
            in_ai_block = False
            continue
        if not stripped:
            continue

        is_ai = full_ai or in_ai_block
        total_nb += 1
        if is_ai:
            ai_nb += 1

        if not stripped.startswith("#"):
            total_code += 1
            if is_ai:
                ai_code += 1

    if in_ai_block:
        raise ValueError(f"Unclosed '# AI Assisted' block in {path}")

    return {
        "total_nb": total_nb,
        "ai_nb": ai_nb,
        "total_code": total_code,
        "ai_code": ai_code,
    }


def _pct(part: int, whole: int) -> float:
    return (100.0 * part / whole) if whole else 0.0


def collect_project_files() -> list[str]:
    """List tracked Python files (falling back to filesystem scan if git is unavailable)."""
    try:
        files = subprocess.check_output(
            ["git", "ls-files", "*.py"], text=True
        ).splitlines()
    except (subprocess.SubprocessError, FileNotFoundError):
        files = [
            str(p.as_posix())
            for p in Path(".").rglob("*.py")
            if not any(part in {"env", ".venv", "venv", ".git"} for part in p.parts)
        ]
    return sorted(f for f in files if f != SELF_PATH)


def main() -> None:
    parser = argparse.ArgumentParser(
        description="Compute unweighted and weighted AI vs. human Python code metrics."
    )
    parser.add_argument(
        "--per-file",
        action="store_true",
        help="Also print the per-file SLOC breakdown.",
    )
    args = parser.parse_args()

    by_cat: dict[str, dict[str, int]] = defaultdict(
        lambda: {"files": 0, "total_nb": 0, "ai_nb": 0, "total_code": 0, "ai_code": 0}
    )
    by_cat_scope: dict[tuple[str, str], dict[str, int]] = defaultdict(
        lambda: {"files": 0, "total_nb": 0, "ai_nb": 0, "total_code": 0, "ai_code": 0}
    )
    overall = {"files": 0, "total_nb": 0, "ai_nb": 0, "total_code": 0, "ai_code": 0}
    per_file: list[tuple[str, str, str, dict[str, int]]] = []

    for rel in collect_project_files():
        counts = count_file(Path(rel))
        if counts["total_nb"] == 0:
            continue
        cat = classify_category(rel)
        scope = classify_scope(rel)
        per_file.append((rel, cat, scope, counts))

        for bucket in (by_cat[cat], by_cat_scope[(cat, scope)], overall):
            bucket["files"] += 1
            for key in ("total_nb", "ai_nb", "total_code", "ai_code"):
                bucket[key] += counts[key]

    weighted_human = 0.0
    weighted_ai = 0.0

    print("=== CATEGORY SUMMARY (SLOC = non-blank, non-# comment lines) ===")
    print(
        f"{'Category':<33} | {'Weight':>6} | {'Files':>5} | {'SLOC':>6} | "
        f"{'Human':>6} | {'AI':>6} | {'Human %':>7} | {'AI %':>6}"
    )
    print("-" * 98)
    for cat, weight in CATEGORY_WEIGHTS.items():
        b = by_cat[cat]
        human = b["total_code"] - b["ai_code"]
        h_pct = _pct(human, b["total_code"])
        a_pct = _pct(b["ai_code"], b["total_code"])
        weighted_human += weight * h_pct
        weighted_ai += weight * a_pct
        print(
            f"{cat:<33} | {weight * 100:5.0f}% | {b['files']:>5} | {b['total_code']:>6} | "
            f"{human:>6} | {b['ai_code']:>6} | {h_pct:6.1f}% | {a_pct:5.1f}%"
        )

    print("-" * 98)
    h_all = overall["total_code"] - overall["ai_code"]
    print(
        f"{'Unweighted Total (Raw SLOC)':<33} | {'—':>6} | {overall['files']:>5} | "
        f"{overall['total_code']:>6} | {h_all:>6} | {overall['ai_code']:>6} | "
        f"{_pct(h_all, overall['total_code']):6.1f}% | "
        f"{_pct(overall['ai_code'], overall['total_code']):5.1f}%"
    )
    print(
        f"{'Weighted Contribution Total':<33} | {'100%':>6} | {overall['files']:>5} | "
        f"{'—':>6} | {'—':>6} | {'—':>6} | {weighted_human:6.1f}% | {weighted_ai:5.1f}%"
    )

    print("\n=== MATRIX: CATEGORY x SUBPROJECT (AI SLOC / Total SLOC) ===")
    print(
        f"{'Category':<33} | {'Problem 1 (BA)':>20} | {'Problem 2 (ES)':>20} | {'Shared / Root':>20}"
    )
    print("-" * 102)
    for cat in CATEGORY_WEIGHTS:
        cells = []
        for scope in SCOPES:
            b = by_cat_scope[(cat, scope)]
            if b["total_code"] == 0:
                cells.append(f"{'—':>20}")
            else:
                cells.append(
                    f"{b['ai_code']:>4}/{b['total_code']:<4} ({_pct(b['ai_code'], b['total_code']):5.1f}%)".rjust(
                        20
                    )
                )
        print(f"{cat:<33} | {' | '.join(cells)}")

    if args.per_file:
        print("\n=== PER-FILE BREAKDOWN (SLOC) ===")
        for rel, cat, _scope, c in per_file:
            print(
                f"  {rel:<54} | {cat:<31} | {c['ai_code']:>4}/{c['total_code']:<4} "
                f"({_pct(c['ai_code'], c['total_code']):5.1f}%)"
            )


if __name__ == "__main__":
    main()
